{
  "name": "LeakFinder Finance",
  "description": "A smart expense tracker that uses AI to detect 'money leaks' like hidden subscriptions and repetitive small habits, helping you save more effectively."
}

export enum Category {
  Food = 'Food',
  Travel = 'Travel',
  Online = 'Online',
  Subscription = 'Subscription',
  Misc = 'Misc'
}

export interface Expense {
  id: string;
  amount: number;
  category: Category;
  description: string;
  date: string;
}

export interface Budget {
  category: Category;
  limit: number;
}

export interface LeakInsight {
  type: 'leak' | 'warning' | 'info';
  title: string;
  message: string;
  potentialSaving?: number;
}

import { Category } from './types';

export const CATEGORIES = [
  Category.Food,
  Category.Travel,
  Category.Online,
  Category.Subscription,
  Category.Misc
];

export const CATEGORY_COLORS: Record<string, string> = {
  [Category.Food]: '#f87171',
  [Category.Travel]: '#60a5fa',
  [Category.Online]: '#c084fc',
  [Category.Subscription]: '#fbbf24',
  [Category.Misc]: '#94a3b8'
};

export const INITIAL_EXPENSES = [
  { id: '1', amount: 45, category: Category.Food, description: 'Afternoon Tea', date: new Date().toISOString() },
  { id: '2', amount: 1200, category: Category.Online, description: 'Amazon shopping', date: new Date().toISOString() },
  { id: '3', amount: 499, category: Category.Subscription, description: 'Netflix', date: new Date().toISOString() },
];

import { GoogleGenAI, Type } from "@google/genai";
import { Expense, LeakInsight } from "../types";

export const analyzeExpenses = async (expenses: Expense[]): Promise<LeakInsight[]> => {
  if (expenses.length < 3) {
    return [{
      type: 'info',
      title: 'Not enough data',
      message: 'Add more expenses for AI-powered leak detection.'
    }];
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Analyze the following expense history for "money leaks" (repetitive small expenses, unnecessary subscriptions, or high category spending). 
  Return exactly 3 insights in JSON format.

  Expenses: ${JSON.stringify(expenses)}

  Focus on:
  1. Repetitive small transactions (e.g. coffee, snacks).
  2. Subscriptions that seem redundant.
  3. Sharp increases in specific categories.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              type: { type: Type.STRING, description: "Must be 'leak', 'warning', or 'info'" },
              title: { type: Type.STRING },
              message: { type: Type.STRING },
              potentialSaving: { type: Type.NUMBER }
            },
            required: ["type", "title", "message"]
          }
        }
      }
    });

    const jsonStr = response.text.trim();
    return JSON.parse(jsonStr) as LeakInsight[];
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return [{
      type: 'warning',
      title: 'Analysis Offline',
      message: 'Could not connect to AI advisor. Check your logs.'
    }];
  }
};

import React, { useMemo } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';
import { Expense, Category } from '../types';
import { CATEGORY_COLORS } from '../constants';

interface DashboardProps {
  expenses: Expense[];
}

const Dashboard: React.FC<DashboardProps> = ({ expenses }) => {
  const categoryData = useMemo(() => {
    const totals: Record<string, number> = {};
    expenses.forEach((e) => {
      totals[e.category] = (totals[e.category] || 0) + e.amount;
    });
    return Object.entries(totals).map(([name, value]) => ({ name, value }));
  }, [expenses]);

  const totalSpent = useMemo(() => expenses.reduce((sum, e) => sum + e.amount, 0), [expenses]);

  const highestCategory = useMemo(() => {
    if (categoryData.length === 0) return 'N/A';
    return categoryData.reduce((prev, current) => (prev.value > current.value) ? prev : current).name;
  }, [categoryData]);

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col justify-between">
          <span className="text-slate-500 text-sm font-medium">Total Spent (Monthly)</span>
          <span className="text-3xl font-bold text-slate-900 mt-2">₹{totalSpent.toLocaleString()}</span>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col justify-between">
          <span className="text-slate-500 text-sm font-medium">Highest Category</span>
          <span className="text-3xl font-bold text-indigo-600 mt-2">{highestCategory}</span>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col justify-between">
          <span className="text-slate-500 text-sm font-medium">Daily Average</span>
          <span className="text-3xl font-bold text-slate-900 mt-2">₹{(totalSpent / 30).toFixed(0)}</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-80">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Spending by Category</h3>
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={categoryData}
                innerRadius={60}
                outerRadius={80}
                paddingAngle={5}
                dataKey="value"
              >
                {categoryData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={CATEGORY_COLORS[entry.name] || '#ccc'} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-80">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Recent Spending Trend</h3>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={expenses.slice(-7)}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="date" tickFormatter={(str) => new Date(str).toLocaleDateString(undefined, { day: 'numeric', month: 'short' })} />
              <YAxis />
              <Tooltip labelFormatter={(str) => new Date(str).toLocaleDateString()} />
              <Bar dataKey="amount" fill="#6366f1" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Category, Expense } from '../types';
import { CATEGORIES } from '../constants';

interface ExpenseFormProps {
  onAdd: (expense: Omit<Expense, 'id'>) => void;
}

const ExpenseForm: React.FC<ExpenseFormProps> = ({ onAdd }) => {
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<Category>(Category.Food);
  const [description, setDescription] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!amount || !description) return;
    onAdd({
      amount: parseFloat(amount),
      category,
      description,
      date: new Date(date).toISOString(),
    });
    setAmount('');
    setDescription('');
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
      <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center">
        <i className="fa-solid fa-plus-circle text-indigo-500 mr-2"></i> Add Expense
      </h2>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-600 mb-1">Amount (₹)</label>
            <input
              type="number"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              placeholder="0.00"
              className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-600 mb-1">Category</label>
            <select
              value={category}
              onChange={(e) => setCategory(e.target.value as Category)}
              className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
            >
              {CATEGORIES.map((cat) => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>
        </div>
        <div>
          <label className="block text-sm font-medium text-slate-600 mb-1">Description</label>
          <input
            type="text"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="What was this for?"
            className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
            required
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-slate-600 mb-1">Date</label>
          <input
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
          />
        </div>
        <button
          type="submit"
          className="w-full py-3 bg-indigo-600 text-white font-bold rounded-lg hover:bg-indigo-700 active:scale-95 transition-all shadow-lg shadow-indigo-100"
        >
          Track Expense
        </button>
      </form>
    </div>
  );
};

export default ExpenseForm;

import React, { useState, useEffect } from 'react';
import { Expense, LeakInsight } from '../types';
import { analyzeExpenses } from '../services/geminiService';

interface LeakInsightsProps {
  expenses: Expense[];
}

const LeakInsights: React.FC<LeakInsightsProps> = ({ expenses }) => {
  const [insights, setInsights] = useState<LeakInsight[]>([]);
  const [loading, setLoading] = useState(false);

  const getInsights = async () => {
    setLoading(true);
    const result = await analyzeExpenses(expenses);
    setInsights(result);
    setLoading(false);
  };

  useEffect(() => {
    if (expenses.length > 0) {
      getInsights();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [expenses.length]);

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-bold text-slate-800 flex items-center">
          <i className="fa-solid fa-wand-magic-sparkles text-amber-500 mr-2"></i> Money Leak Detection
        </h2>
        <button 
          onClick={getInsights} 
          disabled={loading}
          className="text-xs bg-slate-100 hover:bg-slate-200 text-slate-600 px-3 py-1 rounded-full transition-colors font-medium"
        >
          {loading ? 'Analyzing...' : 'Refresh AI'}
        </button>
      </div>

      <div className="space-y-4">
        {loading ? (
          Array(2).fill(0).map((_, i) => (
            <div key={i} className="animate-pulse flex space-x-4 p-4 rounded-xl bg-slate-50">
              <div className="rounded-full bg-slate-200 h-10 w-10"></div>
              <div className="flex-1 space-y-2 py-1">
                <div className="h-4 bg-slate-200 rounded w-3/4"></div>
                <div className="h-3 bg-slate-200 rounded w-5/6"></div>
              </div>
            </div>
          ))
        ) : insights.length > 0 ? (
          insights.map((insight, index) => (
            <div 
              key={index} 
              className={`p-4 rounded-xl border flex items-start space-x-3 transition-all transform hover:scale-[1.01] ${
                insight.type === 'leak' ? 'bg-rose-50 border-rose-100' : 
                insight.type === 'warning' ? 'bg-amber-50 border-amber-100' : 'bg-blue-50 border-blue-100'
              }`}
            >
              <div className={`mt-1 p-2 rounded-lg ${
                insight.type === 'leak' ? 'bg-rose-100 text-rose-600' : 
                insight.type === 'warning' ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'
              }`}>
                <i className={`fa-solid ${
                  insight.type === 'leak' ? 'fa-faucet-drip' : 
                  insight.type === 'warning' ? 'fa-triangle-exclamation' : 'fa-circle-info'
                }`}></i>
              </div>
              <div className="flex-1">
                <h4 className={`font-bold ${
                  insight.type === 'leak' ? 'text-rose-900' : 
                  insight.type === 'warning' ? 'text-amber-900' : 'text-blue-900'
                }`}>
                  {insight.title}
                </h4>
                <p className="text-sm text-slate-600 leading-relaxed">{insight.message}</p>
                {insight.potentialSaving && (
                  <p className="text-xs mt-2 font-bold text-emerald-600">
                    Potential Savings: ₹{insight.potentialSaving}/month
                  </p>
                )}
              </div>
            </div>
          ))
        ) : (
          <div className="text-center py-8 text-slate-400 italic">
            No leaks detected yet. Start tracking!
          </div>
        )}
      </div>
    </div>
  );
};

export default LeakInsights;

import React, { useMemo } from 'react';
import { Expense, Category } from '../types';

interface SmartAlertsProps {
  expenses: Expense[];
}

const SmartAlerts: React.FC<SmartAlertsProps> = ({ expenses }) => {
  const alerts = useMemo(() => {
    const activeAlerts: { title: string; desc: string; severity: 'high' | 'medium' }[] = [];

    // Calculate category spending for the last 7 days
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    const weeklyTotals: Record<string, number> = {};
    expenses.forEach(e => {
      if (new Date(e.date) >= sevenDaysAgo) {
        weeklyTotals[e.category] = (weeklyTotals[e.category] || 0) + e.amount;
      }
    });

    // Rule 1: Food Overspending (> ₹2000 per week)
    if ((weeklyTotals[Category.Food] || 0) > 2000) {
      activeAlerts.push({
        title: 'Food Budget Breached',
        desc: `You spent ₹${weeklyTotals[Category.Food]} on food this week. That's 40% above typical levels!`,
        severity: 'high'
      });
    }

    // Rule 2: Online Shopping Surge
    if ((weeklyTotals[Category.Online] || 0) > 5000) {
      activeAlerts.push({
        title: 'Shopping Spree Detected',
        desc: 'Unusual volume of online orders in the last 7 days.',
        severity: 'medium'
      });
    }

    // Rule 3: Small Repeat Habits (The ₹20-₹50 Leak)
    const smallRepeats = expenses
      .filter(e => e.amount >= 20 && e.amount <= 100 && new Date(e.date) >= sevenDaysAgo)
      .length;
    if (smallRepeats > 10) {
      activeAlerts.push({
        title: 'Micro-leak Alert',
        desc: `You have ${smallRepeats} small transactions (<₹100) this week. These add up quickly!`,
        severity: 'medium'
      });
    }

    return activeAlerts;
  }, [expenses]);

  if (alerts.length === 0) return null;

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
      <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center">
        <i className="fa-solid fa-bell text-rose-500 mr-2"></i> Active Alerts
      </h2>
      <div className="space-y-3">
        {alerts.map((alert, idx) => (
          <div key={idx} className={`p-4 rounded-xl border-l-4 ${
            alert.severity === 'high' ? 'bg-rose-50 border-rose-500 text-rose-800' : 'bg-amber-50 border-amber-500 text-amber-800'
          }`}>
            <h4 className="font-bold">{alert.title}</h4>
            <p className="text-sm mt-1 opacity-90">{alert.desc}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default SmartAlerts;

import React, { useState, useEffect, useCallback } from 'react';
import { Expense, Category } from './types';
import { INITIAL_EXPENSES } from './constants';
import Dashboard from './components/Dashboard';
import ExpenseForm from './components/ExpenseForm';
import LeakInsights from './components/LeakInsights';
import SmartAlerts from './components/SmartAlerts';

const App: React.FC = () => {
  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('leakfinder_expenses');
    return saved ? JSON.parse(saved) : INITIAL_EXPENSES;
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'history'>('dashboard');

  useEffect(() => {
    localStorage.setItem('leakfinder_expenses', JSON.stringify(expenses));
  }, [expenses]);

  const handleAddExpense = (newExpense: Omit<Expense, 'id'>) => {
    const expense: Expense = {
      ...newExpense,
      id: Math.random().toString(36).substr(2, 9),
    };
    setExpenses(prev => [...prev, expense]);
  };

  const handleDeleteExpense = (id: string) => {
    setExpenses(prev => prev.filter(e => e.id !== id));
  };

  return (
    <div className="min-h-screen pb-24 lg:pb-8">
      {/* Header */}
      <header className="bg-white border-b border-slate-100 sticky top-0 z-10 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center space-x-2">
            <div className="bg-indigo-600 text-white p-2 rounded-xl">
              <i className="fa-solid fa-wallet text-xl"></i>
            </div>
            <h1 className="text-2xl font-black text-slate-800 tracking-tight">LeakFinder<span className="text-indigo-600">.</span></h1>
          </div>
          <div className="hidden md:flex space-x-1">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`px-4 py-2 rounded-lg font-semibold transition-all ${activeTab === 'dashboard' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              Overview
            </button>
            <button 
              onClick={() => setActiveTab('history')}
              className={`px-4 py-2 rounded-lg font-semibold transition-all ${activeTab === 'history' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              History
            </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto px-4 py-8">
        {activeTab === 'dashboard' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            {/* Left Column: Input and Alerts */}
            <div className="lg:col-span-4 space-y-8">
              <ExpenseForm onAdd={handleAddExpense} />
              <SmartAlerts expenses={expenses} />
              <LeakInsights expenses={expenses} />
            </div>

            {/* Right Column: Dashboard and Data */}
            <div className="lg:col-span-8 space-y-8">
              <Dashboard expenses={expenses} />

              {/* Mini List */}
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <h3 className="text-lg font-bold text-slate-800 mb-4 flex justify-between items-center">
                  Recent Transactions
                  <button onClick={() => setActiveTab('history')} className="text-sm text-indigo-600 hover:underline">View All</button>
                </h3>
                <div className="space-y-3">
                  {expenses.slice(-5).reverse().map((e) => (
                    <div key={e.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors">
                      <div className="flex items-center space-x-3">
                        <div className="w-10 h-10 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center">
                          <i className={`fa-solid ${e.category === Category.Food ? 'fa-utensils' : e.category === Category.Travel ? 'fa-car' : e.category === Category.Subscription ? 'fa-calendar-check' : 'fa-receipt'}`}></i>
                        </div>
                        <div>
                          <p className="font-bold text-slate-800 text-sm">{e.description}</p>
                          <p className="text-xs text-slate-500 uppercase font-medium">{e.category}</p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="font-bold text-slate-900">₹{e.amount}</p>
                        <p className="text-[10px] text-slate-400">{new Date(e.date).toLocaleDateString()}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
             <div className="flex justify-between items-center mb-6">
               <h2 className="text-2xl font-bold text-slate-800">Transaction History</h2>
               <button onClick={() => setExpenses([])} className="text-sm text-rose-500 hover:bg-rose-50 px-3 py-1 rounded-lg font-medium transition-colors">Clear All Data</button>
             </div>
             <div className="overflow-x-auto">
               <table className="w-full text-left">
                 <thead>
                   <tr className="border-b border-slate-100 text-slate-400 text-sm uppercase">
                     <th className="py-3 px-2">Date</th>
                     <th className="py-3 px-2">Description</th>
                     <th className="py-3 px-2">Category</th>
                     <th className="py-3 px-2 text-right">Amount</th>
                     <th className="py-3 px-2 text-center">Action</th>
                   </tr>
                 </thead>
                 <tbody>
                   {expenses.map((e) => (
                     <tr key={e.id} className="border-b border-slate-50 hover:bg-slate-50 transition-colors">
                       <td className="py-4 px-2 text-sm text-slate-600">{new Date(e.date).toLocaleDateString()}</td>
                       <td className="py-4 px-2 font-medium text-slate-800">{e.description}</td>
                       <td className="py-4 px-2">
                         <span className="text-[10px] px-2 py-1 rounded-full bg-slate-100 font-bold uppercase tracking-wider text-slate-500">{e.category}</span>
                       </td>
                       <td className="py-4 px-2 text-right font-bold text-slate-900">₹{e.amount}</td>
                       <td className="py-4 px-2 text-center">
                         <button onClick={() => handleDeleteExpense(e.id)} className="text-slate-300 hover:text-rose-500 transition-colors">
                           <i className="fa-solid fa-trash-can"></i>
                         </button>
                       </td>
                     </tr>
                   ))}
                 </tbody>
               </table>
               {expenses.length === 0 && <p className="text-center py-12 text-slate-400">No transactions yet.</p>}
             </div>
          </div>
        )}
      </main>

      {/* Mobile Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 px-8 py-4 flex justify-around items-center md:hidden z-20">
        <button 
          onClick={() => setActiveTab('dashboard')}
          className={`flex flex-col items-center space-y-1 ${activeTab === 'dashboard' ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <i className="fa-solid fa-house text-xl"></i>
          <span className="text-[10px] font-bold uppercase">Overview</span>
        </button>
        <button 
          onClick={() => setActiveTab('history')}
          className={`flex flex-col items-center space-y-1 ${activeTab === 'history' ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <i className="fa-solid fa-list text-xl"></i>
          <span className="text-[10px] font-bold uppercase">History</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

