                            e.category === Category.Food ? 'fa-utensils' : 
                            e.category === Category.Travel ? 'fa-car' : 
                            e.category === Category.Online ? 'fa-bag-shopping' : 
                            e.category === Category.Subscription ? 'fa-repeat' : 'fa-receipt'
