                        {/* Details Block */}
                        <div className="min-w-0">
                          <p className="font-black text-slate-900 text-lg truncate leading-tight mb-1">{e.description}</p>
                          <div className="flex flex-wrap items-center gap-y-2 gap-x-4">
                            <div className="flex items-center space-x-1.5">
                              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Category:</span>
                              <span 
                                className="text-[10px] px-2.5 py-1 rounded-lg font-black uppercase tracking-wider border shadow-sm"
                                style={{ 
                                  color: CATEGORY_COLORS[e.category], 
                                  borderColor: `${CATEGORY_COLORS[e.category]}44`,
                                  backgroundColor: `${CATEGORY_COLORS[e.category]}10`
