                              >
                                {e.category}
                              </span>
                            </div>
                            <div className="flex items-center space-x-1.5">
                              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Date:</span>
                              <span className="text-xs font-bold text-slate-600 bg-slate-100 px-2 py-1 rounded-lg">
                                {new Date(e.date).toLocaleDateString(undefined, { day: 'numeric', month: 'long', year: 'numeric' })}
                              </span>
                            </div>
                          </div>
                        </div>
                      </div>

                      {/* Amount Block */}
                      <div className="text-right flex-shrink-0 ml-4">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Amount</span>
                        <p className="text-2xl font-black text-slate-900 tracking-tight">₹{e.amount.toLocaleString()}</p>
                      </div>
                    </div>
                  ))}

                  {expenses.length === 0 && (
                    <div className="text-center py-20 bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
                      <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm">
                        <i className="fa-solid fa-folder-open text-slate-300 text-2xl"></i>
                      </div>
                      <p className="text-slate-500 font-bold">No transactions tracked yet.</p>
                      <p className="text-slate-400 text-sm mt-1">Add your first expense using the form on the left.</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        ) : (
          /* Full History Tab */
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
             <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6">
               <div>
                 <h2 className="text-4xl font-black text-slate-900 tracking-tight">Transaction Archive</h2>
                 <p className="text-slate-500 font-medium text-lg mt-1">A complete record of all your financial movements</p>
               </div>
               <div className="flex items-center space-x-3">
                 <button 
                   onClick={() => { if(confirm('Are you sure you want to delete everything?')) setExpenses([]); }} 
                   className="flex items-center text-sm text-rose-600 bg-rose-50 hover:bg-rose-100 px-6 py-3 rounded-2xl font-black transition-all shadow-sm"
                 >
                   <i className="fa-solid fa-trash-arrow-up mr-2"></i> Wipe Data
                 </button>
               </div>
             </div>

             <div className="overflow-x-auto">
               <table className="w-full text-left border-separate border-spacing-y-4">
                 <thead>
                   <tr className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                     <th className="pb-2 px-6">Transaction Date</th>
                     <th className="pb-2 px-6">Detailed Description</th>
                     <th className="pb-2 px-6">Spending Category</th>
                     <th className="pb-2 px-6 text-right">Total Amount</th>
                     <th className="pb-2 px-6 text-center">Manage</th>
                   </tr>
                 </thead>
                 <tbody>
                   {expenses.slice().reverse().map((e) => (
                     <tr key={e.id} className="group hover:scale-[1.005] transition-all">
                       <td className="py-6 px-6 text-sm font-black text-slate-600 bg-slate-50/50 rounded-l-2xl border-y border-l border-slate-100 group-hover:bg-white group-hover:border-indigo-100">
                         {new Date(e.date).toLocaleDateString(undefined, { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' })}
                       </td>
                       <td className="py-6 px-6 font-black text-slate-900 text-lg bg-slate-50/50 border-y border-slate-100 group-hover:bg-white group-hover:border-indigo-100">
                         <div className="flex items-center space-x-3">
                           <i className={`fa-solid text-slate-300 group-hover:text-indigo-600 transition-colors ${
                              e.category === Category.Food ? 'fa-utensils' : e.category === Category.Travel ? 'fa-car' : 'fa-receipt'
                           }`}></i>
                           <span>{e.description}</span>
                         </div>
                       </td>
                       <td className="py-6 px-6 bg-slate-50/50 border-y border-slate-100 group-hover:bg-white group-hover:border-indigo-100">
                         <span 
                           className="text-[10px] px-3 py-1.5 rounded-xl font-black uppercase tracking-widest border shadow-sm"
                           style={{ 
                             color: CATEGORY_COLORS[e.category], 
                             borderColor: `${CATEGORY_COLORS[e.category]}44`,
                             backgroundColor: `${CATEGORY_COLORS[e.category]}15`
                           }}
                         >
                           {e.category}
                         </span>
                       </td>
                       <td className="py-6 px-6 text-right font-black text-slate-900 text-2xl bg-slate-50/50 border-y border-slate-100 group-hover:bg-white group-hover:border-indigo-100">
                         ₹{e.amount.toLocaleString()}
                       </td>
                       <td className="py-6 px-6 text-center rounded-r-2xl bg-slate-50/50 border-y border-r border-slate-100 group-hover:bg-white group-hover:border-indigo-100">
                         <button 
                           onClick={() => handleDeleteExpense(e.id)} 
                           className="w-10 h-10 rounded-xl text-slate-300 hover:text-rose-600 hover:bg-rose-50 transition-all flex items-center justify-center mx-auto"
                           title="Delete record"
                         >
                           <i className="fa-solid fa-trash-can"></i>
                         </button>
                       </td>
                     </tr>
                   ))}
                 </tbody>
               </table>
               {expenses.length === 0 && (
                 <div className="text-center py-32">
                   <p className="text-slate-400 font-black text-xl">Archive is currently empty.</p>
                   <button onClick={() => setActiveTab('dashboard')} className="mt-4 text-indigo-600 font-bold hover:underline">Click here to add your first expense</button>
                 </div>
               )}
             </div>
          </div>
        )}
      </main>

      {/* Modern Mobile Navigation Bar */}
      <nav className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-900/90 backdrop-blur-xl border border-white/10 px-8 py-3 rounded-3xl flex justify-around items-center md:hidden z-50 shadow-2xl w-[90%]">
        <button 
          onClick={() => setActiveTab('dashboard')}
          className={`flex flex-col items-center space-y-1 p-2 transition-all ${activeTab === 'dashboard' ? 'text-indigo-400 scale-110' : 'text-slate-400'}`}
        >
          <i className="fa-solid fa-grid-2 text-xl"></i>
          <span className="text-[10px] font-black uppercase tracking-tighter">Overview</span>
        </button>
        <button 
          onClick={() => setActiveTab('history')}
          className={`flex flex-col items-center space-y-1 p-2 transition-all ${activeTab === 'history' ? 'text-indigo-400 scale-110' : 'text-slate-400'}`}
        >
          <i className="fa-solid fa-list-check text-xl"></i>
          <span className="text-[10px] font-black uppercase tracking-tighter">Activity</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Category, Expense } from '../types';
import { CATEGORIES } from '../constants';

interface ExpenseFormProps {
  onAdd: (expense: Omit<Expense, 'id'>) => void;
}

const ExpenseForm: React.FC<ExpenseFormProps> = ({ onAdd }) => {
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<Category>(Category.Food);
  const [description, setDescription] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!amount || !description) return;
    onAdd({
      amount: parseFloat(amount),
      category,
      description,
      date: new Date(date).toISOString(),
    });
    setAmount('');
    setDescription('');
  };

  return (
    <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 overflow-hidden relative">
      <div className="absolute top-0 right-0 p-4 opacity-5">
        <i className="fa-solid fa-pen-nib text-6xl -rotate-12"></i>
      </div>

      <h2 className="text-2xl font-black text-slate-900 mb-8 flex items-center">
        <span className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center mr-3">
          <i className="fa-solid fa-plus"></i>
        </span>
        Log Expense
      </h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 gap-6">
          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2.5 ml-1">Spending Amount (₹)</label>
            <div className="relative group">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-black group-focus-within:text-indigo-500">₹</span>
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0.00"
                className="w-full pl-10 pr-4 py-4 bg-slate-50 border border-slate-100 rounded-2xl text-slate-900 font-black text-xl placeholder:text-slate-300 focus:bg-white focus:outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all"
                required
              />
            </div>
          </div>

          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2.5 ml-1">Category Type</label>
            <div className="relative">
              <select
                value={category}
                onChange={(e) => setCategory(e.target.value as Category)}
                className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-2xl text-slate-900 font-bold appearance-none focus:bg-white focus:outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all cursor-pointer"
              >
                {CATEGORIES.map((cat) => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
              </select>
              <i className="fa-solid fa-chevron-down absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"></i>
            </div>
          </div>

          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2.5 ml-1">What did you buy?</label>
            <input
              type="text"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="e.g. Starbucks Coffee"
              className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-2xl text-slate-900 font-bold placeholder:text-slate-300 focus:bg-white focus:outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all"
              required
            />
          </div>

          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2.5 ml-1">Transaction Date</label>
            <input
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-2xl text-slate-900 font-bold focus:bg-white focus:outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all"
            />
          </div>
        </div>

        <button
          type="submit"
          className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl hover:bg-indigo-700 active:scale-[0.97] transition-all shadow-xl shadow-indigo-100 uppercase tracking-[0.2em] text-xs flex items-center justify-center"
        >
          Add to Activity <i className="fa-solid fa-plus-circle ml-3 text-lg"></i>
        </button>
      </form>
    </div>
  );
};

