import React, { useState, useEffect, useMemo } from 'react';
import { Expense, Category } from './types';
import { INITIAL_EXPENSES, CATEGORY_COLORS } from './constants';
import Dashboard from './components/Dashboard';
import ExpenseForm from './components/ExpenseForm';
import LeakInsights from './components/LeakInsights';
import SmartAlerts from './components/SmartAlerts';

const App: React.FC = () => {
  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('leakfinder_expenses');
    return saved ? JSON.parse(saved) : INITIAL_EXPENSES;
  });

  const [monthlyBudget, setMonthlyBudget] = useState<number>(() => {
    const saved = localStorage.getItem('leakfinder_budget');
    return saved ? parseFloat(saved) : 30000;
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'history'>('dashboard');
  const [lastAddedId, setLastAddedId] = useState<string | null>(null);

  // Auto-wipe logic for new month
  useEffect(() => {
    const now = new Date();
    const currentMonthKey = `${now.getFullYear()}-${now.getMonth()}`;
    const lastMonthKey = localStorage.getItem('leakfinder_last_month');

    if (lastMonthKey && lastMonthKey !== currentMonthKey) {
      // It's a new month! Clear data.
      setExpenses([]);
      localStorage.setItem('leakfinder_expenses', JSON.stringify([]));
      console.log("New month detected. Data wiped automatically.");
    }
    localStorage.setItem('leakfinder_last_month', currentMonthKey);
  }, []);

  useEffect(() => {
    localStorage.setItem('leakfinder_expenses', JSON.stringify(expenses));
  }, [expenses]);

  useEffect(() => {
    localStorage.setItem('leakfinder_budget', monthlyBudget.toString());
  }, [monthlyBudget]);

  const handleAddExpense = (newExpense: Omit<Expense, 'id'>) => {
    const id = Math.random().toString(36).substr(2, 9);
    const expense: Expense = {
      ...newExpense,
      id,
    };
    setExpenses(prev => [...prev, expense]);
    setLastAddedId(id);
    setTimeout(() => setLastAddedId(null), 3000);
  };

  const handleDeleteExpense = (id: string) => {
    setExpenses(prev => prev.filter(e => e.id !== id));
  };

  const handleWipeData = () => {
    if (window.confirm('Are you sure you want to delete all transaction records? This cannot be undone.')) {
      setExpenses([]);
      localStorage.removeItem('leakfinder_expenses');
    }
  };

  const daysInMonth = useMemo(() => {
    const now = new Date();
    return new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  }, []);

  const dailyLimit = useMemo(() => monthlyBudget / daysInMonth, [monthlyBudget, daysInMonth]);

  // Format date as DD/MM/YYYY
  const formatDate = (dateStr: string) => {
    const d = new Date(dateStr);
    return `${d.getDate().toString().padStart(2, '0')}/${(d.getMonth() + 1).toString().padStart(2, '0')}/${d.getFullYear()}`;
  };

  return (
    <div className="min-h-screen pb-24 lg:pb-8 bg-slate-50 font-['Inter']">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 py-4 flex justify-between items-center">
          <div className="flex items-center space-x-3">
            <div className="bg-indigo-600 text-white p-2.5 rounded-2xl shadow-lg shadow-indigo-100 ring-4 ring-indigo-50">
              <i className="fa-solid fa-wallet text-xl"></i>
            </div>
            <div>
              <h1 className="text-2xl font-black text-slate-900 leading-none">LeakFinder<span className="text-indigo-600">.</span></h1>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Smart Financial Tracker</p>
            </div>
          </div>

          <div className="flex items-center space-x-2 bg-slate-100 p-1.5 rounded-2xl">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`px-6 py-2.5 rounded-xl font-black text-xs uppercase tracking-wider transition-all ${activeTab === 'dashboard' ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-500 hover:text-slate-800'}`}
            >
              <i className="fa-solid fa-chart-pie mr-2"></i> Overview
            </button>
            <button 
              onClick={() => setActiveTab('history')}
              className={`px-6 py-2.5 rounded-xl font-black text-xs uppercase tracking-wider transition-all ${activeTab === 'history' ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-500 hover:text-slate-800'}`}
            >
              <i className="fa-solid fa-clock-rotate-left mr-2"></i> History ({expenses.length})
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        {activeTab === 'dashboard' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

            <div className="lg:col-span-4 space-y-8">
              {/* Budget Planning Section */}
              <section className="bg-slate-900 text-white p-8 rounded-3xl shadow-xl border border-slate-800 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-10">
                  <i className="fa-solid fa-bullseye text-6xl"></i>
                </div>
                <h2 className="text-xl font-black mb-6 flex items-center">
                  <i className="fa-solid fa-calendar-check text-indigo-400 mr-2"></i> Monthly Planner
                </h2>
                <div className="space-y-4">
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Target Monthly Budget (₹)</label>
                    <input 
                      type="number" 
                      value={monthlyBudget} 
                      onChange={(e) => setMonthlyBudget(parseFloat(e.target.value) || 0)}
                      className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 font-black text-xl text-indigo-300 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                    />
                  </div>
                  <div className="pt-4 border-t border-slate-800">
                    <div className="flex justify-between items-end">
                      <div>
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Smart Daily Limit</p>
                        <p className="text-3xl font-black text-white">₹{dailyLimit.toFixed(0)}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Days Remaining</p>
                        <p className="text-xl font-black text-slate-300">{daysInMonth - new Date().getDate() + 1}</p>
                      </div>
                    </div>
                  </div>
                </div>
              </section>

              <section id="entry-form">
                <ExpenseForm onAdd={handleAddExpense} />
              </section>

              <section id="alerts">
                <SmartAlerts expenses={expenses} />
              </section>

              <section id="ai-insights">
                <LeakInsights expenses={expenses} />
              </section>
            </div>

            <div className="lg:col-span-8 space-y-8">
              <Dashboard expenses={expenses} />

              <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
                  <div>
                    <h3 className="text-2xl font-black text-slate-900 tracking-tight">Recent Activity</h3>
                    <p className="text-slate-500 font-medium text-sm">Latest 10 expenses for this month</p>
                  </div>
                  <button onClick={() => setActiveTab('history')} className="text-sm font-black text-indigo-600 bg-indigo-50 px-5 py-2.5 rounded-xl hover:bg-indigo-100 transition-all">
                    View Full Archive
                  </button>
                </div>

                <div className="grid grid-cols-1 gap-4">
                  {expenses.slice(-10).reverse().map((e) => (
                    <div key={e.id} className={`flex items-center justify-between p-5 bg-white border rounded-2xl transition-all ${lastAddedId === e.id ? 'border-emerald-400 bg-emerald-50 shadow-lg scale-[1.01]' : 'border-slate-100 hover:shadow-md'}`}>
                      <div className="flex items-center space-x-5">
                        <div className="w-14 h-14 rounded-2xl bg-slate-50 text-indigo-600 flex items-center justify-center border border-slate-100">
                          <i className={`fa-solid text-xl ${e.category === Category.Food ? 'fa-utensils' : e.category === Category.Travel ? 'fa-car' : 'fa-receipt'}`}></i>
                        </div>
                        <div>
                          <p className="font-black text-slate-900 text-lg">{e.description}</p>
                          <div className="flex items-center space-x-4 mt-1">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Date: {formatDate(e.date)}</span>
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Cat: {e.category}</span>
                          </div>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="text-2xl font-black text-slate-900">₹{e.amount.toLocaleString()}</p>
                      </div>
                    </div>
                  ))}
                  {expenses.length === 0 && <p className="text-center py-10 text-slate-400 font-medium">No transactions this month.</p>}
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
             <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6">
               <div>
                 <h2 className="text-4xl font-black text-slate-900 tracking-tight">Transaction History</h2>
                 <p className="text-slate-500 font-medium text-lg mt-1">Full records for the current month</p>
               </div>
               <button 
                 onClick={handleWipeData} 
                 className="flex items-center text-sm text-rose-600 bg-rose-50 hover:bg-rose-100 px-8 py-4 rounded-2xl font-black transition-all shadow-sm"
               >
                 <i className="fa-solid fa-trash-arrow-up mr-2"></i> Wipe All Data
               </button>
             </div>

             <div className="overflow-x-auto">
               <table className="w-full text-left border-separate border-spacing-y-4">
                 <thead>
                   <tr className="text-slate-400 text-[10px] font-black uppercase tracking-widest">
                     <th className="pb-2 px-6">Date (DD/MM/YYYY)</th>
                     <th className="pb-2 px-6">Description</th>
                     <th className="pb-2 px-6">Category</th>
                     <th className="pb-2 px-6 text-right">Amount</th>
                     <th className="pb-2 px-6 text-center">Delete</th>
                   </tr>
                 </thead>
                 <tbody>
                   {expenses.slice().reverse().map((e) => (
                     <tr key={e.id} className="group bg-slate-50/50 hover:bg-white transition-all">
                       <td className="py-6 px-6 text-sm font-black text-slate-600 rounded-l-2xl border-y border-l border-slate-100">
                         {formatDate(e.date)}
                       </td>
                       <td className="py-6 px-6 font-black text-slate-900 text-lg border-y border-slate-100">
                         {e.description}
                       </td>
                       <td className="py-6 px-6 border-y border-slate-100">
                         <span className="text-[10px] px-3 py-1.5 rounded-xl font-black uppercase tracking-widest border bg-white" style={{ color: CATEGORY_COLORS[e.category], borderColor: `${CATEGORY_COLORS[e.category]}44` }}>
                           {e.category}
                         </span>
                       </td>
                       <td className="py-6 px-6 text-right font-black text-slate-900 text-2xl border-y border-slate-100">
                         ₹{e.amount.toLocaleString()}
                       </td>
                       <td className="py-6 px-6 text-center rounded-r-2xl border-y border-r border-slate-100">
                         <button onClick={() => handleDeleteExpense(e.id)} className="w-10 h-10 rounded-xl text-slate-300 hover:text-rose-600 transition-all flex items-center justify-center mx-auto">
                           <i className="fa-solid fa-trash-can"></i>
                         </button>
                       </td>
                     </tr>
                   ))}
                 </tbody>
               </table>
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

